// AUTO-GENERATED from rpg_season_events.json by scripts/rpg-character-packs.js.
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.NeoRpgSeasonEvents=api;})(typeof window!=='undefined'?window:null,function(){return Object.freeze({events:[{"id":"neo_community_welcome","title":"The Circuit Opens","kind":"season","priority":100,"earliestDay":1,"trigger":{"all":[{"dayGte":1}]},"delivery":"world","timeCost":0,"expiry":"never","fallback":"queue","lines":[{"speaker":"Narrator","text":"A crooked OPEN sign swings above the card shop door. Inside, a half-finished tournament bracket shares the counter with a pile of unopened packs."},{"speaker":"hana","text":"You must be the new challenger. Sorry about the mess. The bracket printer has opinions."},{"speaker":"Protagonist","text":"I'll help with the bracket if you tell me where my name goes."},{"speaker":"hana","text":"Right under the newcomers. Thanks. Here's your schedule; the first event's on the back."},{"speaker":"Narrator","text":"Hana tries to straighten the sign through the glass. It swings the other way."},{"speaker":"hana","text":"You'll learn your way around. And if you don't, the shop's hard to miss."}],"choices":[{"label":"I want to test my best ideas.","reply":"Good. Try something strange in a practice game before you bring it to the cup.","flag":"welcome_compete","effects":{"flags":["welcome_compete"]}},{"label":"I want to understand this town first.","reply":"Then start with the café. Ask Alma what you should see first.","flag":"welcome_explore","effects":{"flags":["welcome_explore"]}}]},{"id":"neo_community_day","title":"More Than a Bracket","kind":"season","priority":90,"earliestDay":14,"trigger":{"all":[{"dayGte":14}]},"delivery":"world","timeCost":0,"expiry":"never","fallback":"queue","lines":[{"speaker":"Narrator","text":"A noticeboard outside the community center is crowded with volunteers' names and a handwritten request for spare sleeves."},{"speaker":"shiori","text":"Someone's been erasing the same sign-up line for three days."},{"speaker":"Protagonist","text":"The beginner's table?"},{"speaker":"shiori","text":"Mm. They have two decks for six players. The owner of the shop lent them both."},{"speaker":"Narrator","text":"A child approaches with a battered binder. Shiori pulls out a chair before returning to the board."},{"speaker":"shiori","text":"If you have a little time after your next match, they'd welcome another opponent."}],"choices":[{"label":"I can offer advice when I have time.","reply":"Thank you. Even one game would help. They keep running out of practice partners.","flag":"community_volunteer","effects":{"flags":["community_volunteer"]}},{"label":"I will cheer the volunteers on.","reply":"I'll tell them there's another friendly face in the crowd.","flag":"community_encourage","effects":{"flags":["community_encourage"]}}]},{"id":"neo_cup_eve","title":"Before the Neighborhood Cup","kind":"season","priority":90,"earliestDay":29,"trigger":{"all":[{"dayGte":29}]},"delivery":"world","timeCost":0,"expiry":"never","fallback":"queue","lines":[{"speaker":"Narrator","text":"At the card shop, people crowd around a bracket penciled onto the back of a shipping carton. The Neighborhood Cup is tomorrow."},{"speaker":"reina","text":"Half those predictions are wrong already. They listed someone who's out of town."},{"speaker":"Protagonist","text":"You sound awfully sure of yourself."},{"speaker":"reina","text":"I'm sure of the matchup. The cards can still make a fool of me."},{"speaker":"Narrator","text":"Reina flips a single test card onto the table, then leaves the rest of the deck face down."},{"speaker":"reina","text":"Got a minute? I want to see whether this opening's as bad as it looks."}],"choices":[{"label":"I will review my opening hands.","reply":"Good. Deal seven. We can find the ugly draws before tomorrow.","flag":"cup_practice","effects":{"flags":["cup_practice"]}},{"label":"I want to see who surprises everyone.","reply":"If you're watching, pay attention to the quiet games. That's where the strange decks hide.","flag":"cup_watch","effects":{"flags":["cup_watch"]}}]},{"id":"neo_qualifier_eve","title":"The Regional Qualifier Approaches","kind":"season","priority":90,"earliestDay":59,"trigger":{"all":[{"dayGte":59}]},"delivery":"world","timeCost":0,"expiry":"never","fallback":"queue","lines":[{"speaker":"Narrator","text":"A new qualifier bracket has been pinned above the community center's old results. Beside it sits a box of mismatched pens."},{"speaker":"akari","text":"Someone filled in the finalist before registration closed."},{"speaker":"Protagonist","text":"That's a confident prediction."},{"speaker":"akari","text":"Or lazy bookkeeping. They're not remotely the same thing."},{"speaker":"Narrator","text":"She quietly crosses out the penciled name and offers the marker to the next player waiting in line."},{"speaker":"akari","text":"We should make sure everyone gets their place on the sheet first. After that, let them surprise us."}],"choices":[{"label":"I will prepare what I can.","reply":"Then bring the list you've actually tested. I'll be curious how it holds up.","flag":"qualifier_prepare","effects":{"flags":["qualifier_prepare"]}},{"label":"I will support the players who enter.","reply":"I'll save a seat by the last table. Those games are usually better than the predictions.","flag":"qualifier_support","effects":{"flags":["qualifier_support"]}}]},{"id":"neo_final_preparations","title":"A Town Preparing","kind":"season","priority":90,"earliestDay":87,"trigger":{"all":[{"dayGte":87}]},"delivery":"world","timeCost":0,"expiry":"never","fallback":"queue","lines":[{"speaker":"Narrator","text":"Championship posters have gone up along the waterfront. In the shop window, a sun-faded schedule from the first week still hangs beneath the new one."},{"speaker":"hana","text":"Look at that. I never took the old schedule down."},{"speaker":"Protagonist","text":"You could leave it there."},{"speaker":"hana","text":"It has someone's tea stain on it. And the wrong start time for the second cup."},{"speaker":"Narrator","text":"She smooths one corner against the glass, careful not to tear the paper."},{"speaker":"hana","text":"After the final, I'm making everybody bring a deck back here. Win or lose."}],"choices":[{"label":"One more practice session sounds right.","reply":"All right, but eat something before the match. You keep forgetting.","flag":"finale_focus","effects":{"flags":["finale_focus"]}},{"label":"I want to thank the people who helped.","reply":"You should. I still have the signup sheet from the first week.","flag":"finale_gratitude","effects":{"flags":["finale_gratitude"]}}]},{"id":"neo_season_closure","title":"The Harbor Remembers","kind":"season","priority":999,"earliestDay":91,"trigger":{"all":[{"dayGte":91}]},"delivery":"world","timeCost":0,"expiry":"never","fallback":"queue","closure":true,"lines":[{"speaker":"Narrator","text":"The last tournament notices come down. The shop keeps one page from the final results book on the counter."},{"speaker":"Narrator","text":"The season record reads: {{seasonRecord}}. {{championshipRecord}}"},{"speaker":"Narrator","text":"A second page holds the names from your time around town. {{friendshipRecord}}"},{"speaker":"shiori","text":"The café's still open, if you want to sit for a while."},{"speaker":"Protagonist","text":"Feels strange without another round on the schedule."},{"speaker":"Narrator","text":"Shiori closes the results book and leaves it beside the spare decks."},{"speaker":"shiori","text":"Then perhaps next time we can play without looking at the clock."}],"choices":[{"label":"I am ready for whatever comes next.","reply":"I'll put the kettle on. Someone will arrive with a deck before the water boils.","flag":"season_keep_going","effects":{"flags":["season_keep_going"]}},{"label":"I want a moment to remember it.","reply":"There's no rush. The chairs aren't going anywhere.","flag":"season_reflect","effects":{"flags":["season_reflect"]}}]},{"id":"barb_asks_for_help","title":"A Little Help With the Corners","kind":"bond","priority":60,"earliestDay":23,"trigger":{"all":[{"storyDone":"barb_route_1"},{"relationship":{"npc":"barb","metric":"trust","gte":2}}]},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"barb","text":"Hey. Do you remember that first display you helped me fix?"},{"speaker":"Protagonist","text":"The one with the pink paper stars?"},{"speaker":"barb","text":"That's the one. I saved one star for the next design. Wanted to tell you before I put it somewhere permanent."}],"choices":[{"label":"That means a lot.","reply":"It does to me too. Don't go getting dramatic about it.","flag":"barb_star_thanks","effects":{"flags":["barb_star_thanks"]}},{"label":"Show me when it is ready.","reply":"Deal. First look is yours—unless I glue my hands to the table again.","flag":"barb_star_later","effects":{"flags":["barb_star_later"]}}],"characterId":"barb"},{"id":"elena_asks_for_help","title":"The Unscheduled Hour","kind":"bond","priority":60,"earliestDay":36,"trigger":{"all":[{"storyDone":"elena_route_2"},{"relationship":{"npc":"elena","metric":"trust","gte":2}}]},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"elena","text":"I have a problem I cannot fit into a tidy calendar slot."},{"speaker":"Protagonist","text":"That sounds unlike you. Is everything okay?"},{"speaker":"elena","text":"I promised to organize the community study night, and the room booking collapsed. I know how to fix plans, but I am less practiced at asking people for help."},{"speaker":"elena","text":"Would you be willing to look at the alternatives with me when you are free?"}],"choices":[{"label":"I can help you think it through.","reply":"Thank you. I will bring the messy draft, not just the polished version.","flag":"elena_help_yes","effects":{"flags":["elena_help_yes"]}},{"label":"I am busy today, but you can ask others too.","reply":"You are right. Asking is not an imposition, even when the answer is no.","flag":"elena_help_no","effects":{"flags":["elena_help_no"]}}],"characterId":"elena"},{"id":"jinx_after_setback","title":"Off the Scoreboard","kind":"bond","priority":60,"earliestDay":40,"trigger":{"all":[{"storyDone":"jinx_route_2"},{"relationship":{"npc":"jinx","metric":"respect","gte":2}}]},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"jinx","text":"I lost a match I thought I had solved. Go on, say something clever."},{"speaker":"Protagonist","text":"Would you rather talk about the game or leave it alone?"},{"speaker":"jinx","text":"Huh. I expected you to pretend it did not matter. It does. I made a bad read."},{"speaker":"jinx","text":"If you ever want to look at that turn with me, I might even listen. No promises."}],"choices":[{"label":"We can study the board, no excuses.","reply":"Fine. Bring your sharpest notes. I need something better than sympathy.","flag":"jinx_review_yes","effects":{"flags":["jinx_review_yes"]}},{"label":"You do not owe me a replay of that loss.","reply":"Good. I wanted you to know anyway.","flag":"jinx_review_no","effects":{"flags":["jinx_review_no"]}}],"characterId":"jinx"},{"id":"luna_tests_independence","title":"Her Own Line","kind":"bond","priority":60,"earliestDay":40,"trigger":{"all":[{"storyDone":"luna_route_2"},{"relationship":{"npc":"luna","metric":"trust","gte":2}}]},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"luna","text":"I rebuilt my deck. Alone. Do not look so surprised."},{"speaker":"Protagonist","text":"What did you change?"},{"speaker":"luna","text":"I took out the flashy combo everyone told me I needed. I want to see whether my idea can stand on its own."},{"speaker":"luna","text":"You can test it with me, but promise you will not solve my turns for me."}],"choices":[{"label":"Deal. I will play seriously and let you decide.","reply":"That is exactly what I wanted to hear.","flag":"luna_test_yes","effects":{"flags":["luna_test_yes"]}},{"label":"I cannot test it now, but it is your deck.","reply":"Yes! I want the decision to be mine, even if I lose.","flag":"luna_test_no","effects":{"flags":["luna_test_no"]}}],"characterId":"luna"},{"id":"lyla_invoice_deadline","title":"A Payment Worth Chasing","kind":"bond","priority":55,"earliestDay":25,"trigger":{"all":[{"storyDone":"lyla_route_2"},{"relationship":{"npc":"lyla","metric":"trust","gte":2}}]},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"lyla","text":"The lookbook client paid. After two reminders and a very polite legal-sounding email."},{"speaker":"Protagonist","text":"Does that mean the Umbreon fund is safe?"},{"speaker":"lyla","text":"Rent first. Umbreon second. But yes. I wanted someone to tell."}],"choices":[{"label":"Celebrate with a card shop visit","reply":"That is, surprisingly, exactly what I wanted to hear.","flag":"lyla_invoice_cards","effects":{"flags":["lyla_invoice_cards"]}},{"label":"Tell her she earned every cent","reply":"I did. It feels good to hear that said plainly.","flag":"lyla_invoice_worth","effects":{"flags":["lyla_invoice_worth"]}}],"characterId":"lyla"},{"id":"lyla_campaign_correction","title":"The Revised Campaign","kind":"bond","priority":65,"earliestDay":40,"trigger":{"storyDone":"lyla_route_3"},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"lyla","text":"Remember the sportswear advertisement? They accepted the new wording."},{"speaker":"Protagonist","text":"So no more miracle abs in ten days?"},{"speaker":"lyla","text":"Just comfortable clothes and actual movement. Almost revolutionary."}],"choices":[{"label":"Congratulate her on standing firm","reply":"Thanks. It was a small fight. Still worth winning.","flag":"lyla_ad_truth","effects":{"flags":["lyla_ad_truth"]}},{"label":"Ask her to show you the finished ad","reply":"Sure. I like the photo now that I can stand behind the words.","flag":"lyla_ad_preview","effects":{"flags":["lyla_ad_preview"]}}],"characterId":"lyla"},{"id":"lyla_print_kept_private","title":"Not for the Portfolio","kind":"bond","priority":70,"earliestDay":66,"trigger":{"storyDone":"lyla_route_5"},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"lyla","text":"They asked if I wanted the laughing picture in my portfolio. The one from the park."},{"speaker":"Protagonist","text":"What did you say?"},{"speaker":"lyla","text":"No. I asked for a print for myself. That's different."}],"choices":[{"label":"You don't owe anyone that moment","reply":"Exactly. Some things can just be mine.","flag":"lyla_private_smile","effects":{"flags":["lyla_private_smile"]}},{"label":"I'd like to see the print someday","reply":"Maybe. I'll decide when.","flag":"lyla_private_print","effects":{"flags":["lyla_private_print"]}}],"characterId":"lyla"},{"id":"lyla_final_booking","title":"A Better Contract","kind":"bond","priority":75,"earliestDay":82,"trigger":{"storyDone":"lyla_route_6"},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"lyla","text":"The agency offered me another contract. Fewer hours and approval over the photos."},{"speaker":"Protagonist","text":"Are you taking it?"},{"speaker":"lyla","text":"I think so. Not because I love the work. Because it finally leaves me room to love other things."}],"choices":[{"label":"Then there'll be more time for cards","reply":"The best clause in the contract, actually.","flag":"lyla_time_for_cards","effects":{"flags":["lyla_time_for_cards"]}},{"label":"I'm happy you get to choose","reply":"Me too. I needed that more than a bigger fee.","flag":"lyla_contract_choice","effects":{"flags":["lyla_contract_choice"]}}],"characterId":"lyla"},{"id":"rina_initiates_practice","title":"Practice on Her Terms","kind":"bond","priority":60,"earliestDay":30,"trigger":{"all":[{"storyDone":"rina_route_2"},{"relationship":{"npc":"rina","metric":"trust","gte":2}}]},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"rina","text":"This is going to sound ridiculous, but I put a practice match on my rehearsal calendar."},{"speaker":"Protagonist","text":"Did your manager approve it?"},{"speaker":"rina","text":"She asked if it was a new song. I said no. The drummer offered to test my deck after soundcheck anyway."},{"speaker":"rina","text":"I've got two openings I can't decide between. Would you play a few hands with me sometime?"}],"choices":[{"label":"I'd love to. You pick the table.","reply":"Yes! And bring that awful disruption deck. I need the practice.","flag":"rina_practice_yes","effects":{"flags":["rina_practice_yes"]}},{"label":"I can't make it this week.","reply":"Okay! Send me a message when you've got an evening free.","flag":"rina_practice_no","effects":{"flags":["rina_practice_no"]}}],"characterId":"rina"},{"id":"sierra_defines_boundaries","title":"Both Sides of the Lens","kind":"bond","priority":60,"earliestDay":48,"trigger":{"all":[{"storyDone":"sierra_route_2"},{"relationship":{"npc":"sierra","metric":"respect","gte":2}}]},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"sierra","text":"My photo shoot moved onto the day I had reserved for tournament practice. Everyone thinks I should pick one dream."},{"speaker":"Protagonist","text":"Do you have to choose forever, or just work out tomorrow?"},{"speaker":"sierra","text":"That is the question I needed. I love both. I just need people to respect the time I set aside for each."},{"speaker":"sierra","text":"Would you help me test a shorter practice plan sometime? Only when we both agree on a time."}],"choices":[{"label":"Of course. Your time belongs to you.","reply":"Thank you. I can be serious about both without apologizing.","flag":"sierra_plan_yes","effects":{"flags":["sierra_plan_yes"]}},{"label":"I am booked, but your boundaries make sense.","reply":"No problem. I can make my own plan too.","flag":"sierra_plan_no","effects":{"flags":["sierra_plan_no"]}}],"characterId":"sierra"},{"id":"sol_invites_quiet","title":"A Plan With No Plan","kind":"bond","priority":60,"earliestDay":44,"trigger":{"all":[{"storyDone":"sol_route_2"},{"relationship":{"npc":"sol","metric":"trust","gte":2}}]},"delivery":"remote_or_present","timeCost":0,"fallback":"queue","expiry":"never","lines":[{"speaker":"sol","text":"Important question: does a sunset count as an event if I don't print tickets?"},{"speaker":"Protagonist","text":"Are you planning something?"},{"speaker":"sol","text":"Jun confiscated my clipboard. I was going to argue, but the harbor looks pretty good without a schedule."},{"speaker":"sol","text":"I can bring lemonade. Want to sit by the water for a bit? That's the entire invitation. Suspicious, I know."}],"choices":[{"label":"Lemonade and a sunset sound good.","reply":"Great. I'll bring two cups and exactly zero whistles.","flag":"sol_quiet_yes","effects":{"flags":["sol_quiet_yes"]}},{"label":"Not today. Rain check?","reply":"Absolutely. I might even manage to keep the lemonade cold until next time.","flag":"sol_quiet_no","effects":{"flags":["sol_quiet_no"]}}],"characterId":"sol"}]});});
